export function EventHandler({
  eventType = "{{eventType}}",
  handlerName = "{{handlerName}}",
  effectText = "{{effectText}}",
  accent = "{{accent}}",
}) {
  return (
    <div style={{ font: "12px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 300, boxSizing: "border-box", display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap", justifyContent: "center" }}>
      <div style={{ border: `2px solid ${accent}`, borderRadius: 8, padding: "10px 14px", fontWeight: 700 }}>
        Element
        <span style={{ display: "block", fontFamily: "ui-monospace, monospace", fontSize: 10, fontWeight: 400, color: "#24143099", marginTop: 3 }}>on{eventType}</span>
      </div>
      <span aria-hidden="true" style={{ fontSize: 14, color: "#24143060" }}>&rarr;</span>
      <code style={{ fontFamily: "ui-monospace, monospace", fontSize: 11, background: "#24143012", padding: "6px 8px", borderRadius: 6 }}>{handlerName}()</code>
      <span aria-hidden="true" style={{ fontSize: 14, color: "#24143060" }}>&rarr;</span>
      <div style={{ padding: "10px 14px", borderRadius: 8, fontWeight: 600, textAlign: "center", background: accent }}>{effectText}</div>
    </div>
  );
}
